package com.encounterledger;

import java.lang.reflect.*;
import java.util.*;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class CoxCaptureTest {
    @Test public void distinguishesLobbyStartAndPartialJoin() {
        CoxCapture c=new CoxCapture();
        assertNull(c.poll(true,0)); assertEquals(Boolean.TRUE,c.poll(true,1));
        c.ended(); assertNull(c.poll(true,1));
        c.poll(false,0); assertEquals(Boolean.FALSE,c.poll(true,1));
        c.reset(); c.message("The raid has begun!"); assertEquals(Boolean.TRUE,c.poll(true,1));
    }
    @Test public void parsesCompletionAndLimitsChatCapture() {
        CoxCapture c=new CoxCapture(); c.poll(true,0); c.poll(true,1);
        c.message("Map Layout: Challenge Mode (Full).");
        assertEquals("Challenge Mode (Full).",c.layout);
        c.message("<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>2 players</col> Duration: <col=ff0000>23:25.20</col> Personal best: 19:38.40");
        assertTrue(c.complete); assertEquals(1405200L,c.timing.get("durationMs"));
        assertEquals(2,c.timing.get("teamSize"));
        assertFalse(CoxCapture.recognized("hello clan"));
    }
    private static void set(Object o,String name,Object v)throws Exception {
        Field f=EncounterLedgerPlugin.class.getDeclaredField(name);f.setAccessible(true);f.set(o,v);
    }
    private static Object get(Object o,String name)throws Exception {
        Field f=EncounterLedgerPlugin.class.getDeclaredField(name);f.setAccessible(true);return f.get(o);
    }
    interface Answer { Object value(String method,Object[] args); }
    @SuppressWarnings("unchecked") private static <T>T fake(Class<T> type,Answer answer) {
        return (T)Proxy.newProxyInstance(type.getClassLoader(),new Class<?>[]{type},(p,m,a)->{
            Object v=answer.value(m.getName(),a);if(v!=null)return v;
            if(m.getReturnType()==boolean.class)return false;
            if(m.getReturnType()==int.class)return 0;return null;
        });
    }
    static class Recorder extends EncounterLedgerPlugin {
        Map<String,Object> saved;
        @Override void saveEncounter(Map<String,Object> log){saved=log;}
    }
    @Test public void recordsQuietRoomsDeathAndCompletionBeyondGenericLimit()throws Exception {
        int[] state={0}, inside={1}, tick={0}, projectileReads={0};
        Player player=fake(Player.class,(m,a)->m.equals("getWorldLocation")?new WorldPoint(3200,3200,0):null);
        Client client=fake(Client.class,(m,a)->{
            if(m.equals("getLocalPlayer"))return player;
            if(m.equals("getGameState"))return GameState.LOGGED_IN;
            if(m.equals("isClientThread"))return true;
            if(m.equals("getTickCount"))return tick[0];
            if(m.equals("getProjectiles")){projectileReads[0]++;return null;}
            if(m.equals("getBoostedSkillLevel")||m.equals("getRealSkillLevel"))return 99;
            if(m.equals("getVarbitValue"))return ((Integer)a[0])==5432?inside[0]:((Integer)a[0])==5425?state[0]:0;
            return null;
        });
        Recorder p=new Recorder();set(p,"client",client);
        set(p,"config",fake(EncounterLedgerConfig.class,(m,a)->m.equals("idleTicks")?15:null));
        p.onGameTick(new GameTick()); assertNull(get(p,"encounter"));
        state[0]=1;
        for(int i=0;i<2010;i++){tick[0]++;p.onGameTick(new GameTick());}
        assertNotNull(get(p,"encounter")); assertNull(p.saved);
        assertTrue("CoX requests raw projectiles without an individual boss profile",projectileReads[0]>0);
        p.onActorDeath(new ActorDeath(player));
        set(p,"bossDeathPending",true);p.onGameTick(new GameTick());assertNull(p.saved);
        ChatMessage message=new ChatMessage();message.setType(ChatMessageType.FRIENDSCHAT);
        message.setMessage("Congratulations - your raid is complete! Team size: 2 players Duration: 25:46.20");
        p.onChatMessage(message);p.onGameTick(new GameTick());assertNull(p.saved);
        message.setType(ChatMessageType.FRIENDSCHATNOTIFICATION);p.onChatMessage(message);
        p.onGameTick(new GameTick());assertEquals("raid_complete",p.saved.get("endReason"));
        assertEquals("Chambers of Xeric",p.saved.get("label"));
        p.onGameTick(new GameTick());assertNull(get(p,"encounter"));
        // Reset in the lobby, start a new raid, and allow an exit grace period.
        state[0]=0;p.onGameTick(new GameTick());state[0]=1;p.onGameTick(new GameTick());p.saved=null;
        inside[0]=0;p.onGameTick(new GameTick());p.onGameTick(new GameTick());assertNull(p.saved);
        p.onGameTick(new GameTick());assertEquals("left_raid",p.saved.get("endReason"));
        inside[0]=1;state[0]=0;p.onGameTick(new GameTick());state[0]=1;p.onGameTick(new GameTick());p.saved=null;
        GameStateChanged lost=new GameStateChanged();lost.setGameState(GameState.CONNECTION_LOST);p.onGameStateChanged(lost);
        assertEquals("connection_lost",p.saved.get("endReason"));
    }
}

package com.encounterledger;

import java.lang.reflect.*;
import java.util.*;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class BossBoundaryTest
{
    interface Answer { Object get(String method); }
    @SuppressWarnings("unchecked") static <T> T fake(Class<T> type, Answer answer) {
        return (T) Proxy.newProxyInstance(type.getClassLoader(),new Class<?>[]{type},(p,m,a)-> {
            Object value=answer.get(m.getName()); if(value!=null)return value;
            if(m.getReturnType()==boolean.class)return false;
            if(m.getReturnType()==int.class)return 0;
            return null;
        });
    }
    static class Capture extends EncounterLedgerPlugin {
        Boolean area;
        @Override Boolean encounterArea(Player player,BossProfile profile) { return area; }
        List<Map<String,Object>> saved=new ArrayList<>();
        @Override void saveEncounter(Map<String,Object> log) { saved.add(log); }
    }
    static class Enemy {
        boolean dead; int ratio=100;
        NPC npc;
        Enemy(int id) { npc=fake(NPC.class,m->{
            if(m.equals("getId"))return id;
            if(m.equals("getName"))return id==14176?"Yama":"Add";
            if(m.equals("isDead"))return dead;
            if(m.equals("getHealthRatio"))return ratio;
            return null;
        }); }
    }
    static class Harness {
        Capture plugin=new Capture();
        Enemy boss=new Enemy(14176);
        Actor target=boss.npc;
        int clock;
        Harness() throws Exception {
            Player player=fake(Player.class,m->{
                if(m.equals("getInteracting"))return target;
                if(m.equals("getWorldLocation"))return new WorldPoint(3200,3200,0);
                return null;
            });
            Client client=fake(Client.class,m->{
                if(m.equals("getLocalPlayer"))return player;
                if(m.equals("getGameState"))return GameState.LOGGED_IN;
                if(m.equals("isClientThread"))return true;
                if(m.equals("getBoostedSkillLevel")||m.equals("getRealSkillLevel"))return 99;
                if(m.equals("getTickCount"))return clock;
                return null;
            });
            set("client",client);
            set("config",new EncounterLedgerConfig(){});
        }
        void set(String name,Object value)throws Exception {Field f=EncounterLedgerPlugin.class.getDeclaredField(name);f.setAccessible(true);f.set(plugin,value);}
        void tick(){clock++;plugin.onGameTick(new GameTick());}
        void hit(Enemy e){HitsplatApplied event=new HitsplatApplied();event.setActor(e.npc);event.setHitsplat(fake(Hitsplat.class,m->{
            if(m.equals("isMine"))return true;
            if(m.equals("getHitsplatType"))return HitsplatID.DAMAGE_ME;
            if(m.equals("getAmount"))return 10;
            return null;
        }));plugin.onHitsplatApplied(event);}
    }
    @SuppressWarnings("unchecked") static List<Map<String,Object>> ticks(Map<String,Object> log){return (List<Map<String,Object>>)log.get("ticks");}
    @Test public void scurriusKeepsQuietArenaAndSeparatesPostKillRats()throws Exception {
        Harness h=new Harness();h.boss=new Enemy(7222);h.target=h.boss.npc;h.plugin.area=true;
        h.hit(h.boss);h.tick();for(int i=0;i<40;i++)h.tick();assertTrue(h.plugin.saved.isEmpty());
        h.boss.dead=true;h.plugin.onActorDeath(new ActorDeath(h.boss.npc));h.tick();
        assertEquals("boss_death",h.plugin.saved.get(0).get("endReason"));
        Enemy rat=new Enemy(7223);h.target=rat.npc;h.hit(rat);h.tick();
        Field encounter=EncounterLedgerPlugin.class.getDeclaredField("encounter");encounter.setAccessible(true);
        assertNull(encounter.get(h.plugin));
        Enemy next=new Enemy(7222);h.target=next.npc;h.hit(next);h.tick();assertNotNull(encounter.get(h.plugin));
        h.plugin.area=false;h.tick();h.tick();assertEquals(1,h.plugin.saved.size());h.tick();
        assertEquals("left_encounter",h.plugin.saved.get(1).get("endReason"));
        assertEquals("rock_impact",ScurriusProfile.INSTANCE.groundHazard(2644));
    }
    @Test public void preRollIsBoundedAndDoesNotExtendDeathTail()throws Exception {
        Harness h=new Harness();for(int i=0;i<20;i++)h.tick();h.hit(h.boss);h.tick();
        h.plugin.onActorDeath(new ActorDeath(h.boss.npc));h.tick();for(int i=0;i<16;i++)h.tick();
        Map<String,Object> log=h.plugin.saved.get(0);assertEquals(15,log.get("combatStartTick"));
        assertEquals(17,ticks(log).size());assertEquals(16,log.get("endTick"));
        for(int i=0;i<17;i++)assertEquals(i,ticks(log).get(i).get("tick"));
    }
    @Test public void killKeepsFinalHitAndDeathTickAndNoIdleTail()throws Exception {
        Harness h=new Harness();h.hit(h.boss);h.tick();
        h.plugin.onActorDeath(new ActorDeath(h.boss.npc));
        h.hit(h.boss);h.tick();
        for(int i=0;i<16;i++)h.tick();
        assertEquals(1,h.plugin.saved.size());
        Map<String,Object> log=h.plugin.saved.get(0);
        assertEquals("boss_death",log.get("endReason"));assertEquals(1,log.get("endTick"));
        assertEquals(2,ticks(log).size());
        List<?> events=(List<?>)ticks(log).get(1).get("events");assertEquals(2,events.size());
        for(int i=0;i<20;i++){h.hit(h.boss);h.tick();}
        for(int i=0;i<16;i++)h.tick();
        assertEquals(1,h.plugin.saved.size());assertEquals(2,ticks(log).size());
    }
    @Test public void addsAndLivingDespawnDoNotEndFight()throws Exception {
        Harness h=new Harness();h.hit(h.boss);h.tick();
        Enemy judge=new Enemy(14180);h.hit(judge);
        h.plugin.onActorDeath(new ActorDeath(judge.npc));h.plugin.onNpcDespawned(new NpcDespawned(h.boss.npc));h.tick();
        assertTrue(h.plugin.saved.isEmpty());
        h.plugin.onActorDeath(new ActorDeath(h.boss.npc));h.tick();for(int i=0;i<16;i++)h.tick();assertEquals(1,h.plugin.saved.size());
    }
    @Test public void oneHitKillWorksWithoutSelectedTarget()throws Exception {
        Harness h=new Harness();h.target=null;h.hit(h.boss);h.plugin.onActorDeath(new ActorDeath(h.boss.npc));h.tick();
        for(int i=0;i<16;i++)h.tick();
        assertEquals(1,ticks(h.plugin.saved.get(0)).size());assertEquals("Yama",h.plugin.saved.get(0).get("label"));
    }
    @Test public void zeroHpSnapshotAndNextFightAreHandled()throws Exception {
        Harness h=new Harness();h.hit(h.boss);h.tick();h.boss.ratio=0;h.tick();
        for(int i=0;i<16;i++)h.tick();
        assertEquals("zero_hp_snapshot",h.plugin.saved.get(0).get("endEvidence"));
        Enemy next=new Enemy(14176);h.target=next.npc;h.hit(next);h.tick();
        h.plugin.onActorDeath(new ActorDeath(next.npc));h.tick();for(int i=0;i<16;i++)h.tick();assertEquals(2,h.plugin.saved.size());
        assertEquals(0,ticks(h.plugin.saved.get(1)).get(0).get("tick"));
    }
    @Test public void unrelatedYamaDeathDoesNotEndLocalFight()throws Exception {
        Harness h=new Harness();h.hit(h.boss);h.tick();h.plugin.onActorDeath(new ActorDeath(new Enemy(14176).npc));h.tick();
        assertTrue(h.plugin.saved.isEmpty());
    }
    @Test public void transitionWithoutCombatSurvivesIdleThenExitEnds()throws Exception {
