package com.encounterledger;
import java.util.*;
import net.runelite.api.*;
import net.runelite.api.gameval.VarbitID;
/** Boss-independent observed state. Timer values are retained without inventing source items. */
final class SharedBuffs {
 static Map<String,Object> state(boolean active,int raw,int unit){
  Map<String,Object> s=new LinkedHashMap<>();s.put("active",active);s.put("rawValue",raw);
  if(unit>0){s.put("remainingTicksUpperBound",Math.max(0,raw)*unit);s.put("timerResolutionTicks",unit);}
  return s;
 }
 static void timer(Map<String,Object> out,Client c,String id,int varbit,int unit){int raw=c.getVarbitValue(varbit);out.put(id,state(raw>0,raw,unit));}
 @SuppressWarnings("unchecked") static void merge(Map<String,Object> out,String id,int value){int raw=(Integer)((Map<String,Object>)out.get(id)).get("rawValue");if(value>raw)out.put(id,state(true,value,1));}
 static Map<String,Object> snapshot(Client c){
  Map<String,Object> out=new LinkedHashMap<>();
  timer(out,c,"heart_cooldown",VarbitID.IMBUED_HEART_TIMER,10);
  timer(out,c,"saturated_heart",VarbitID.SATURATED_HEART_TIME,0);
  timer(out,c,"prayer_regeneration",VarbitID.PRAYER_REGENERATION_POTION_TIMER,12);
  timer(out,c,"goading",VarbitID.GOADING_POTION_TIMER,6);
  timer(out,c,"menaphite_remedy",VarbitID.STATRENEWAL_POTION_TIMER,25);
  timer(out,c,"antifire",VarbitID.ANTIFIRE_POTION,30);
  timer(out,c,"super_antifire",VarbitID.SUPER_ANTIFIRE_POTION,20);
  out.put("stamina",state(c.getVarbitValue(VarbitID.STAMINA_ACTIVE)>0,c.getVarbitValue(VarbitID.STAMINA_DURATION),10));
  timer(out,c,"divine_attack",VarbitID.DIVINEATTACK_POTION_TIME,1);
  timer(out,c,"divine_strength",VarbitID.DIVINESTRENGTH_POTION_TIME,1);
  timer(out,c,"divine_defence",VarbitID.DIVINEDEFENCE_POTION_TIME,1);
  timer(out,c,"divine_ranged",VarbitID.DIVINERANGE_POTION_TIME,1);
  timer(out,c,"divine_magic",VarbitID.DIVINEMAGIC_POTION_TIME,1);
  int combat=c.getVarbitValue(VarbitID.DIVINECOMBAT_POTION_TIME),bastion=c.getVarbitValue(VarbitID.DIVINEBASTION_POTION_TIME),battle=c.getVarbitValue(VarbitID.DIVINEBATTLEMAGE_POTION_TIME);
  merge(out,"divine_attack",combat);merge(out,"divine_strength",combat);merge(out,"divine_defence",Math.max(combat,Math.max(bastion,battle)));merge(out,"divine_ranged",bastion);merge(out,"divine_magic",battle);
  int poison=c.getVarpValue(net.runelite.api.gameval.VarPlayerID.POISON);
  boolean helm=false;
  ItemContainer gear=c.getItemContainer(InventoryID.EQUIPMENT);
  if(gear!=null && c.getVarbitValue(VarbitID.CHARGES_SERPENTINE_HELM_QUANTITY)>0){
   for(Item item:gear.getItems())if(item.getId()>=0){String name=c.getItemDefinition(item.getId()).getName();
    if(name.equals("Serpentine helm")||name.equals("Tanzanite helm")||name.equals("Magma helm"))helm=true;
   }
  }
  out.put("poison_immunity",state(poison<0||helm,poison,0));
  out.put("venom_immunity",state(poison < -38||helm,poison,0));
  out.put("preserve",state(c.isPrayerActive(Prayer.PRESERVE),0,0));
  for(Skill skill:new Skill[]{Skill.ATTACK,Skill.STRENGTH,Skill.DEFENCE,Skill.RANGED,Skill.MAGIC}){
   int base=c.getRealSkillLevel(skill),current=c.getBoostedSkillLevel(skill);
   Map<String,Object> s=state(current>base,current,0);s.put("base",base);s.put("current",current);
   out.put("boost_"+skill.name().toLowerCase(Locale.ROOT),s);
  }
  return out;
 }
}

package com.encounterledger;

/** Boss rules are opt-in by NPC ID; unknown encounters never inherit another boss's rules. */
interface BossProfile
{
    default boolean completionMessage(String text) { return false; }
    default boolean requiresCompletionMessage() { return false; }
    String id();
    String name();
    boolean matches(int npcId);
    String[] animation(int npcId, int animationId);
    String[] projectile(int graphicId);
    String[] spawn(int npcId);
    String[] overhead(String text);
    String[] graphic(int graphicId, boolean localPlayer);
    String[] announcement(String text);
    default String groundHazard(int graphicId) { return null; }
    default String hazardProtection(int graphicId) { return null; }
    default String replayProjectile(int graphicId) { return null; }
    default boolean observesNpcDamage(int npcId) { return matches(npcId); }
    default boolean includesSpatialNpc(int npcId) { return false; }
    default boolean hasEncounterArea() { return false; }
    default boolean containsEncounterTile(net.runelite.api.coords.WorldPoint tile, boolean instanced) { return false; }

    static BossProfile forNpc(int npcId) { return YamaProfile.INSTANCE.matches(npcId) ? YamaProfile.INSTANCE : ScurriusProfile.INSTANCE.matches(npcId) ? ScurriusProfile.INSTANCE : VorkathProfile.INSTANCE.matches(npcId) ? VorkathProfile.INSTANCE : RoyalTitansProfile.INSTANCE.matches(npcId) ? RoyalTitansProfile.INSTANCE : ResearchBossProfile.forNpc(npcId); }
}

package com.encounterledger;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;

/** Observed visual anchors only: animation extent is not a server collision footprint. */
final class HazardRecorder {
    private final PositionRecorder positions=new PositionRecorder();
    /** Preserve separate objects, including scheduled visuals; never merge them into a damage count. */
    Map<String,Object> atHit(Client client, Player player, BossProfile profile) {
        Map<String,Object> result=new LinkedHashMap<>();
        List<Map<String,Object>> observations=new ArrayList<>();
        boolean available=player!=null && profile!=null && client.getGraphicsObjects()!=null;
        boolean truncated=false;
        if(available) for(GraphicsObject g:client.getGraphicsObjects()) {
            String type=profile.groundHazard(g.getId());
            if(type==null || g.finished() || g.getLocation()==null || g.getWorldView()!=player.getWorldView())continue;
            WorldPoint world=WorldPoint.fromLocal(g.getWorldView(),g.getLocation().getX(),g.getLocation().getY(),g.getLevel());
            if(player.getWorldLocation()==null || world.distanceTo(player.getWorldLocation())>2)continue;
            WorldPoint p=positions.normalise(client,g.getWorldView(),world);
            if(p==null)continue;
            if(observations.size()>=256){truncated=true;break;}
            Map<String,Object> tile=new LinkedHashMap<>();tile.put("x",p.getX());tile.put("y",p.getY());tile.put("plane",p.getPlane());
            Map<String,Object> observation=new LinkedHashMap<>();
            observation.put("observationIndex",observations.size());
            observation.put("graphicId",g.getId());observation.put("type",type);observation.put("position",tile);
            observation.put("startCycle",g.getStartCycle());observation.put("scheduled",g.getStartCycle()>client.getGameCycle());
            observations.add(observation);
        }
        result.put("basis","client_visual_observations");result.put("clientCycle",client.getGameCycle());
        result.put("available",available);result.put("truncated",truncated);result.put("radiusTiles",2);
        result.put("observations",observations);
        return result;
    }
    List<Map<String,Object>> snapshot(Client client, Player player, BossProfile profile) {
        List<Map<String,Object>> result=new ArrayList<>();
        if(profile==null || player==null || client.getGraphicsObjects()==null)return result;
        for(GraphicsObject graphic:client.getGraphicsObjects()) {
            String type=profile.groundHazard(graphic.getId());
            if(type==null || graphic.finished() || graphic.getStartCycle()>client.getGameCycle()
                || graphic.getWorldView()!=player.getWorldView() || graphic.getLocation()==null)continue;
            WorldPoint world=WorldPoint.fromLocal(graphic.getWorldView(),graphic.getLocation().getX(),graphic.getLocation().getY(),graphic.getLevel());
            WorldPoint point=positions.normalise(client,graphic.getWorldView(),world);
            if(point==null)continue;
            Map<String,Object> tile=new LinkedHashMap<>();
            tile.put("x",point.getX());tile.put("y",point.getY());tile.put("plane",point.getPlane());
            Map<String,Object> hazard=new LinkedHashMap<>();
            hazard.put("type",type);hazard.put("graphicId",graphic.getId());hazard.put("position",tile);
            hazard.put("startCycle",graphic.getStartCycle());hazard.put("animationFrame",graphic.getAnimationFrame());
            result.add(hazard);
            if(result.size()>=256)break;
        }
        return result;
    }
    List<String> possibleSources(Client client,Player player,BossProfile profile) {
        Map<String,Object> tile=positions.position(client,player);
        return overlaps(tile,snapshot(client,player,profile),protections(client,player,profile));
    }
    List<String> protections(Client client,Player player,BossProfile profile) {
        Set<String> result=new LinkedHashSet<>();
        if(profile!=null && player!=null && player.getSpotAnims()!=null)for(ActorSpotAnim spot:player.getSpotAnims()) {
            String type=profile.hazardProtection(spot.getId());
            if(type!=null && spot.getStartCycle()<=client.getGameCycle())result.add(type);
        }
        return new ArrayList<>(result);
    }
    static List<String> overlaps(Map<String,Object> tile,List<Map<String,Object>> hazards,List<String> protections) {
        Set<String> types=new LinkedHashSet<>();
        if(tile!=null)for(Map<String,Object> hazard:hazards)
            if(("fire_wave".equals(hazard.get("type")) || "shadow_wave".equals(hazard.get("type"))) && tile.equals(hazard.get("position")) && !protections.contains(hazard.get("type")))types.add((String)hazard.get("type"));
        return new ArrayList<>(types);
    }
}

