package com.encounterledger;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;

/** End-of-tick server tiles, normalised to the instance template rather than the camera. */
final class PositionRecorder {
    private final Map<NPC,Integer> identities = new IdentityHashMap<>();
    private int nextIdentity;
    private final Map<String,Integer> participantIds=new HashMap<>();
    private static Map<String,Object> map(Object... fields) {
        Map<String,Object> result=new LinkedHashMap<>();
        for(int i=0;i<fields.length;i+=2)result.put((String)fields[i],fields[i+1]);
        return result;
    }
    WorldPoint normalise(Client client, WorldView view, WorldPoint world) {
        if(view==null || world==null)return null;
        if(!view.isInstance())return world;
        LocalPoint local=LocalPoint.fromWorld(view,world);
        if(local==null)return null;
        int[][][] chunks=view.getInstanceTemplateChunks();
        int x=local.getSceneX()/8,y=local.getSceneY()/8,p=world.getPlane();
        if(chunks==null || p<0 || p>=chunks.length || x<0 || x>=chunks[p].length || y<0 || y>=chunks[p][x].length || chunks[p][x][y]==-1)return null;
        return WorldPoint.fromLocalInstance(client,local,p);
    }
    Map<String,Object> position(Client client,Actor actor) {
        if(actor==null)return null;
        WorldPoint point=normalise(client,actor.getWorldView(),actor.getWorldLocation());
        return point==null?null:map("x",point.getX(),"y",point.getY(),"plane",point.getPlane());
    }
    Map<String,Object> snapshot(Client client,Player player) {
        return snapshot(client,player,null);
    }
    Map<String,Object> snapshot(Client client,Player player,BossProfile profile) {
        List<Map<String,Object>> npcs=new ArrayList<>();
        List<NPC> visible=client.getNpcs();
        // Scaled raid NPCs can report level zero. Capture the loaded raid actors
        // independently of target selection; the usual view/range/cap checks still apply.
        boolean activeRaid=client.getVarbitValue(CoxCapture.IN_RAID)==1
            && client.getVarbitValue(CoxCapture.RAID_STATE)>0;
        boolean truncated=false;
        if(visible!=null) for(NPC npc:visible) {
            if(npc.getWorldView()!=player.getWorldView() || npc.getWorldLocation()==null || player.getWorldLocation()==null
                || npc.getWorldLocation().distanceTo(player.getWorldLocation())>48)continue;
            // Include combat NPCs plus Yama's encounter actors; omit decorative non-combat NPCs.
            if(!activeRaid && npc.getCombatLevel()<=0 && npc.getId()!=14176 && npc.getId()!=14179 && npc.getId()!=14180 && npc!=player.getInteracting()
                && (profile==null || !profile.includesSpatialNpc(npc.getId())))continue;
            Map<String,Object> position=position(client,npc);
            if(position==null)continue;
            if(npcs.size()>=128){truncated=true;break;}
            NPCComposition composition=npc.getTransformedComposition();
            int size=composition==null?1:Math.max(1,Math.min(64,composition.getSize()));
            // Rotated template chunks can change which corner is southwest.
            WorldPoint world=npc.getWorldLocation();
            int minX=(Integer)position.get("x"),minY=(Integer)position.get("y"),maxX=minX,maxY=minY;
            boolean footprintKnown=composition!=null;
            for(int dx:new int[]{0,size-1})for(int dy:new int[]{0,size-1}) {
                WorldPoint corner=normalise(client,npc.getWorldView(),world.dx(dx).dy(dy));
                if(corner==null || corner.getPlane()!=(Integer)position.get("plane")){footprintKnown=false;continue;}
                minX=Math.min(minX,corner.getX());minY=Math.min(minY,corner.getY());maxX=Math.max(maxX,corner.getX());maxY=Math.max(maxY,corner.getY());
            }
            footprintKnown=footprintKnown && maxX-minX+1==size && maxY-minY+1==size;
            if(footprintKnown) {position.put("x",minX);position.put("y",minY);}
            int identity=identities.computeIfAbsent(npc,n->++nextIdentity);
            npcs.add(map("id",npc.getId(),"index",npc.getIndex(),"identity",identity,"name",npc.getName()==null?"NPC":net.runelite.client.util.Text.removeTags(npc.getName()),
                "position",position,"size",footprintKnown?size:1,"footprintKnown",footprintKnown,"dead",npc.isDead(),"animationId",npc.getAnimation(),
                "actorVisuals",ActorVisualSnapshot.capture(npc,client.getGameCycle())));
        }
        Map<String,Object> result=map("coordinateSystem","instance_template","player",position(client,player),"npcs",npcs,"truncated",truncated);
        result.put("playerVisuals",ActorVisualSnapshot.capture(player,client.getGameCycle()));
        if(participantScope(client,player,profile)) {
            List<Map<String,Object>> participants=new ArrayList<>();boolean clipped=false;
            if(client.getPlayers()!=null)for(Player other:client.getPlayers()) {
                if(other==player||other.getName()==null||other.getWorldView()!=player.getWorldView()||other.getWorldLocation()==null||other.getWorldLocation().distanceTo(player.getWorldLocation())>48)continue;
                Map<String,Object> tile=position(client,other);if(tile==null)continue;
                if(profile!=null && profile.hasEncounterArea() && !profile.containsEncounterTile(normalise(client,other.getWorldView(),other.getWorldLocation()),other.getWorldView().isInstance()))continue;
                if(participants.size()>=100){clipped=true;break;}
                String displayName=net.runelite.client.util.Text.removeTags(other.getName()).replace('\u00a0',' ').replace('_',' ').trim();
                if(displayName.isEmpty() || displayName.length()>64)continue;
                String name=displayName.toLowerCase(Locale.ROOT);
                if(!participantIds.containsKey(name)&&participantIds.size()>=100){clipped=true;continue;}
                int id=participantIds.computeIfAbsent(name,k->participantIds.size()+2);
                participants.add(map("identity",id,"name",displayName,"position",tile));
            }
            result.put("players",participants);result.put("playersTruncated",clipped);
            result.put("participantCapture", "visible_encounter_players_v1");
        }
        List<Map<String,Object>> glyphs=glyphs(client,player);
        if(glyphs!=null)result.put("glyphs",glyphs);
        if(profile==VorkathProfile.INSTANCE) {
            List<Map<String,Object>> acid=acidPools(client,player);
            if(acid!=null)result.put("acidPools",acid);
        }
        return result;
    }
    static String glyphState(int id) {
        if(id==56335 || id==56336)return "active";
        if(id==56337)return "inactive";
        if(id==56338 || id==56339)return "fading";
        return null;
    }
    // Snapshot scene objects so pre-existing glyphs, transforms and removals are all observed.
    // RuneLite gameval ObjectID1: FLOORKIT_SUMMONING03_FULL01/02, INACTIVE, DEACTIVATE.
    private List<Map<String,Object>> glyphs(Client client,Player player) {
        WorldView view=player.getWorldView();
        WorldPoint p=normalise(client,view,player.getWorldLocation());
        if(p==null || p.getRegionID()!=6045)return null;
        Scene scene=view.getScene();
        if(scene==null || scene.getTiles()==null)return null;
        int plane=player.getWorldLocation().getPlane();
        Tile[][][] tiles=scene.getTiles();
        if(plane<0 || plane>=tiles.length)return null;
        Set<TileObject> seen=Collections.newSetFromMap(new IdentityHashMap<>());
        List<Map<String,Object>> result=new ArrayList<>();
        for(Tile[] row:tiles[plane])if(row!=null)for(Tile tile:row)if(tile!=null) {
            List<TileObject> objects=new ArrayList<>();
            objects.add(tile.getGroundObject());objects.add(tile.getDecorativeObject());objects.add(tile.getWallObject());
            if(tile.getGameObjects()!=null)Collections.addAll(objects,tile.getGameObjects());
            for(TileObject object:objects) {
                if(object==null || !seen.add(object))continue;
                // Only inspect the known Yama glyph family, never arbitrary scene definitions.
                int id=object.getId();
                if(glyphState(id)==null)continue;
                ObjectComposition definition=client.getObjectDefinition(id);
                if(definition!=null && definition.getImpostorIds()!=null) {
                    definition=definition.getImpostor();
                    if(definition==null)continue;
                    id=definition.getId();
                }
                String state=glyphState(id);
                WorldPoint point=normalise(client,view,object.getWorldLocation());
                if(state==null || point==null || point.getRegionID()!=6045)continue;
                result.add(map("id",id,"state",state,"position",map("x",point.getX(),"y",point.getY(),"plane",point.getPlane())));
            }
        }
        return result;
    }
    private List<Map<String,Object>> acidPools(Client client,Player player) {
        WorldView view=player.getWorldView();
        WorldPoint p=normalise(client,view,player.getWorldLocation());
        if(view==null||!VorkathProfile.INSTANCE.containsEncounterTile(p,view.isInstance())||view.getScene()==null)return null;
        Tile[][][] tiles=view.getScene().getTiles();int plane=player.getWorldLocation().getPlane();
        if(tiles==null||plane<0||plane>=tiles.length)return null;
        List<Map<String,Object>> result=new ArrayList<>();
        Set<TileObject> seen=Collections.newSetFromMap(new IdentityHashMap<>());
        for(Tile[] row:tiles[plane])if(row!=null)for(Tile tile:row)if(tile!=null){
            List<TileObject> objects=new ArrayList<>();objects.add(tile.getGroundObject());
            if(tile.getGameObjects()!=null)Collections.addAll(objects,tile.getGameObjects());
            for(TileObject object:objects){
                if(object==null||object.getId()!=32000||!seen.add(object))continue;
                WorldPoint point=normalise(client,view,object.getWorldLocation());
                if(!VorkathProfile.INSTANCE.containsEncounterTile(point,true))continue;
                result.add(map("x",point.getX(),"y",point.getY(),"plane",point.getPlane()));
                if(result.size()>256)return null;
            }
        }
        return result;
    }
    private boolean participantScope(Client client,Player player,BossProfile profile) {
        if(player==null||player.getWorldView()==null||player.getWorldLocation()==null)return false;
        if(profile==YamaProfile.INSTANCE || profile==ScurriusProfile.INSTANCE || profile==RoyalTitansProfile.INSTANCE)return profile.containsEncounterTile(normalise(client,player.getWorldView(),player.getWorldLocation()),player.getWorldView().isInstance());
        return client.getVarbitValue(CoxCapture.IN_RAID)==1 && client.getVarbitValue(CoxCapture.RAID_STATE)>0;
    }
    void reset() {identities.clear();nextIdentity=0;participantIds.clear();}
}

package com.encounterledger;

final class CombatMath
{
    private CombatMath() {}
    // A residual, not an authoritative food/healing event. Missing damage and overkill affect it.
    static int healingEstimate(int previousHp, int currentHp, int damage)
    {
        return previousHp < 0 ? 0 : Math.max(0, currentHp - previousHp + damage);
    }
    static boolean isHpDamage(int type, boolean mine, boolean others)
    {
        return mine || others || type == 65 || type == 5 || type == 67 || type == 74;
    }
}

package com.encounterledger;

/** IDs from RuneLite gameval AnimationID/SpotanimID. See docs/boss-events.md. */
final class YamaProfile implements BossProfile
{
    static final YamaProfile INSTANCE = new YamaProfile();
    public String id() { return "yama"; }
    public String name() { return "Yama"; }
    public boolean matches(int npcId) { return npcId == 14176; }
    public boolean hasEncounterArea() { return true; }
    // Template region containing the arena, Judge islands and stepping stones.
    public boolean containsEncounterTile(net.runelite.api.coords.WorldPoint tile, boolean instanced) {
        return instanced && tile != null && tile.getPlane()==0 && tile.getRegionID()==6045;
    }
    // Research capture: moving stepping-stone fire spells are non-combat NPCs.
    public boolean includesSpatialNpc(int npcId) { return npcId==13507; }
    public String groundHazard(int graphicId) {
        if(graphicId==2856)return "skull_impact";
        // An effect ID may be delivered as a scene graphic rather than a Projectile.
        String projectile=replayProjectile(graphicId);
        if(projectile!=null)return projectile;
        if(graphicId==3251 || graphicId==3252)return "skull_impact";
        if(graphicId==3255 || graphicId==3262)return "rock_impact";
        if(graphicId>=3263 && graphicId<=3266)return "shadow_wave";
        if(graphicId>=3267 && graphicId<=3269)return "fire_wave";
        return null;
    }
    public String replayProjectile(int graphicId) {
        if(graphicId==2855)return "flaming_skull";
        if(graphicId==3250)return "flaming_skull";
        if(graphicId==3254)return "flaming_rock";
        if(graphicId>=3271 && graphicId<=3273)return "meteor";
        return null;
    }
    public boolean observesNpcDamage(int npcId) { return matches(npcId) || npcId==14180; }
    public String hazardProtection(int graphicId) {
        return graphicId==3280?"fire_wave":graphicId==3281?"shadow_wave":null;
    }
    public String[] announcement(String text) {
        text=text.replaceAll("@[a-zA-Z0-9_]+@", "").trim();
        if (text.equals("You've been seared to the ground!")) return new String[]{"fire_streak_injury", "Fire streak movement disruption", "fire"};
        if (text.equals("You absorb a Glyph of Fire.")) return new String[]{"fire_glyph_activation", "Fire glyph activation cost", "fire"};
        if (text.equals("You've been injured and can't use protection prayers!")) return new String[]{"shadow_wave_injury", "Shadow wave prayer disruption", "shadow"};
        if (!text.startsWith("Yama conjures") || text.length() > 240) return null;
        String lower = text.toLowerCase(java.util.Locale.ROOT);
        String category = lower.contains("shadow") ? "shadow" : lower.contains("fire") || lower.contains("flam") || lower.contains("meteor") ? "fire" : "summon";
        return new String[]{"special_announcement", text, category};
    }
    public String[] spawn(int id) {
        if (id == 14179) return new String[]{"void_flare_spawn", "Void flare summoned", "summon"};
        if (id == 14180) return new String[]{"judge_spawn", "Judge of Yama appears", "phase"};
        return null;
    }
    public String[] overhead(String text) {
        return java.util.Arrays.asList("Begone", "Begone!", "You bore me.", "Enough.").contains(text)
            ? new String[]{"intermission", "Yama intermission", "phase"} : null;
    }
    public String[] graphic(int id, boolean localPlayer) {
