package com.encounterledger;

import java.util.*;
import java.util.regex.*;

/** Evidence only: never substitute observed replay length for the game timer. */
final class KillTiming {
    static void observed(Map<String,Object> timing, java.time.Instant at, int clientTick) {
        if(timing==null)return;
        timing.putIfAbsent("receivedAt",at.toString());
        timing.putIfAbsent("receivedClientTick",clientTick);
    }
    private static final Pattern DURATION = Pattern.compile("^Fight duration: (\\d{1,3}):([0-5]\\d)(?:\\.(\\d{1,2}))?(?:\\. Personal best:.*| \\(new personal best\\).*)?$");
    static Map<String,Object> parse(String message) {
        message=message.replaceAll("@[A-Za-z0-9_]+@", "").replaceAll("<[^>]*>", "").trim();
        Matcher m=DURATION.matcher(message);
        if(!m.matches())return null;
        int millis=Integer.parseInt(m.group(1))*60000+Integer.parseInt(m.group(2))*1000;
        if(m.group(3)!=null)millis+=Integer.parseInt(m.group(3))*(m.group(3).length()==1?100:10);
        if(millis<=0)return null;
        Map<String,Object> out=new LinkedHashMap<>();
        out.put("source","game_duration_message");out.put("durationMs",millis);out.put("message",message);
        out.put("precisionMs",m.group(3)==null?1000:m.group(3).length()==1?100:10);
        return out;
    }
}

package com.encounterledger;

import java.util.*;
import net.runelite.api.*;

/** Raw client observations. An empty visual list never asserts server-side immunity. */
final class ActorVisualSnapshot {
    static final int LIMIT = 32;
    static Map<String,Object> capture(Actor actor, int cycle) {
        Map<String,Object> result = new LinkedHashMap<>();
        List<Map<String,Object>> graphics = new ArrayList<>();
        boolean available = actor != null && actor.getSpotAnims() != null;
        boolean truncated = false;
        if (available) for (ActorSpotAnim spot : actor.getSpotAnims()) {
            if (graphics.size() >= LIMIT) { truncated = true; break; }
            Map<String,Object> graphic = new LinkedHashMap<>();
            graphic.put("id", spot.getId());
            graphic.put("startCycle", spot.getStartCycle());
            graphic.put("scheduled", spot.getStartCycle() > cycle);
            graphics.add(graphic);
        }
        result.put("basis", "client_visual_observations");
        result.put("clientCycle", cycle);
        result.put("available", available);
        result.put("truncated", truncated);
        result.put("graphics", graphics);
        if (actor instanceof NPC) {
            NPCComposition composition = ((NPC) actor).getTransformedComposition();
            if (composition != null) result.put("transformedNpcId", composition.getId());
        }
        return result;
    }
}

package com.encounterledger;

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

final class RecordingFolder {
    static String name(String boss, String id) {
        return name(boss,id,LocalDateTime.now());
    }
    static String logFile(Map<String,Object> log) {
        String id=UUID.fromString(String.valueOf(log.get("id"))).toString();
        if(log.containsKey("researchSessionId"))return id+".json";
        LocalDateTime started=Instant.parse(String.valueOf(log.get("startedAt"))).atZone(ZoneId.systemDefault()).toLocalDateTime();
        return name((String)log.get("label"),id,started)+".json";
    }
    private static String name(String boss,String id,LocalDateTime time) {
        String label=net.runelite.client.util.Text.removeTags(boss==null?"PvM":boss).replaceAll("[^A-Za-z0-9_-]+","-").replaceAll("^-+|-+$","");
        if(label.isEmpty())label="PvM";
        label=label.substring(0,Math.min(48,label.length()));
        return label+"_"+time.format(DateTimeFormatter.ofPattern("yyyy-MM-dd_HH-mm-ss"))+"_"+UUID.fromString(id);
    }
    static String validate(String folder,String id) {
        String uuid=UUID.fromString(id).toString();
        if(folder.equals(uuid)||folder.matches("[A-Za-z0-9_-]{1,100}_"+uuid))return folder;
        throw new IllegalArgumentException("Invalid recording folder");
    }
}

